#!/bin/bash
set -Eeuo pipefail
umask 077
python3 <<'PYCHECK'
from pathlib import Path
import os,json,lzma,base64,urllib.request,hashlib,tempfile,subprocess,shutil
files=json.loads(lzma.decompress(base64.b64decode('')))
d=Path(tempfile.mkdtemp(prefix='celikom-m4a98-check-',dir='/tmp'))
try:
 os.chown(d,0,33);d.chmod(0o750)
 for name,content in files.items():
  p=d/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content);os.chown(p,0,33);p.chmod(0o640)
 tools=d/'server/tools';tools.mkdir(parents=True,exist_ok=True)
 for p in d.rglob('*'):
  if p.is_dir():os.chown(p,0,33);p.chmod(0o750)
 req=urllib.request.Request('https://api.github.com/repos/manufact-test/nomusic/git/blobs/39123c9b511625fc2b2fb7598863bb7a33991512',headers={'User-Agent':'CELIKOM-verified-tool-check','Accept':'application/vnd.github+json'})
 with urllib.request.urlopen(req,timeout=35) as response:data=response.read(8*1024*1024+1)
 assert len(data)<=8*1024*1024
 obj=json.loads(data);assert obj['sha']=='39123c9b511625fc2b2fb7598863bb7a33991512' and obj['encoding']=='base64'
 binary=base64.b64decode(obj['content']);assert len(binary)==3805992 and hashlib.sha256(binary).hexdigest()=='c0f2d9b74c0f1f4e19605d45dbaf3e31e75411a53da4f1ceb172c1e2e0b86d63'
 p=tools/'m4a-normalizer';p.write_bytes(binary);os.chown(p,0,33);p.chmod(0o750)
 for i in range(2):
  p=tools/('decode-slot-'+str(i)+'.lock');p.touch();os.chown(p,0,33);p.chmod(0o660)
 for p in d.rglob('*.php'):
  r=subprocess.run(['runuser','-u','www-data','--','php','-l',str(p)],capture_output=True,text=True,timeout=10)
  if r.returncode:print(r.stdout[:1000],r.stderr[:1000]);raise RuntimeError('PHP_LINT_FAILED')
 r=subprocess.run(['runuser','-u','www-data','--','php',str(d/'server/tests/m4a-normalization.php'),str(d/'extension/tests/fixtures/m4a-normalization.json')],capture_output=True,text=True,timeout=100)
 print(r.stdout[-5000:],end='')
 if r.returncode:print(r.stderr[-3000:]);raise RuntimeError('M4A_MATRIX_FAILED')
 print('M4A_098_PHP_AND_MINIMAL_TOOL_CHECKED')
finally:shutil.rmtree(d)
PYCHECK
